// Actual 32x16 RGB JPEG containing only a flat synthetic background, no plate.
// Generated locally for QA and deliberately independent of OCR model accuracy.
const jpegBase64 =
  "";

export function issue429SyntheticJpeg() {
  const bytes = Buffer.from(jpegBase64, "base64");
  if (bytes.length < 64 || bytes.length > 1024 * 1024 ||
      bytes[0] !== 0xff || bytes[1] !== 0xd8 ||
      bytes.at(-2) !== 0xff || bytes.at(-1) !== 0xd9) {
    throw new Error("Issue429 embedded synthetic JPEG integrity check failed.");
  }
  return bytes;
}
